    """Help formatter that escapes literal percent signs in argument help text."""

    def _get_help_string(self, action):
        help_text = super()._get_help_string(action)
        escaped = []
        index = 0
        while index < len(help_text):
            if help_text[index] != "%":
                escaped.append(help_text[index])
                index += 1
            elif index + 1 < len(help_text) and help_text[index + 1] in ("%", "("):
                escaped.append(help_text[index : index + 2])
                index += 2
