class _RuleRF06SQLiteFixMixin:
    """Add SQLite fixes for identifiers matching keywords."""

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        cls.config_keywords = list(cls.config_keywords) + [
            "prefer_quoted_keyword_style"
        ]
        original_eval = cls._eval

        def _eval(self, context):
            result = original_eval(self, context)
            segment = context.segment

            if (
                context.dialect.name != "sqlite"
                or not self.prefer_quoted_keywords
                or not segment.is_type("naked_identifier", "quoted_identifier")
            ):
                return result

            raw = segment.raw
            if segment.is_type("quoted_identifier"):
                if raw.startswith("[") and raw.endswith("]"):
                    identifier = raw[1:-1]
                elif raw[:1] in {'"', "`"} and raw.endswith(raw[0]):
                    identifier = raw[1:-1]
                else:
                    return result
            else:
                identifier = raw

            keywords = context.dialect.sets("reserved_keywords") | context.dialect.sets(
                "unreserved_keywords"
            )
            if identifier.upper() not in keywords:
                return result

            style = (
                getattr(self, "prefer_quoted_keyword_style", None) or "double_quotes"
            )
            quote = '"' if style == "double_quotes" else "`"
            quoted_identifier = f"{quote}{identifier}{quote}"
            if raw == quoted_identifier:
                return result

            from sqlfluff.core.rules import LintFix, LintResult

            return LintResult(
                anchor=segment,
                fixes=[
                    LintFix.replace(
                        segment,
                        [segment.edit(raw=quoted_identifier)],
                    )
                ],
            )

        cls._eval = _eval


