    """Group configured settings ahead of settings using their defaults."""
    import contextlib
    import functools
    import io
    import sys

    @functools.wraps(callback)
    def wrapper(*args, **kwargs):
        if kwargs.get("extras"):
            return callback(*args, **kwargs)

        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            result = callback(*args, **kwargs)

        lines = output.getvalue().splitlines(keepends=True)
        first_setting = next(
            (
                index
                for index, line in enumerate(lines)
                if not line[:1].isspace() and " [env:" in line
            ),
            None,
        )
        if first_setting is None:
            sys.stdout.write(output.getvalue())
            return result

        extras_start = next(
            (
                index
                for index, line in enumerate(lines[first_setting:], first_setting)
                if not line[:1].isspace()
                and " [env:" not in line
                and line.strip().lower().startswith(("custom", "extra", "plugin extra"))
            ),
            len(lines),
        )

        prefix = lines[:first_setting]
        suffix = lines[extras_start:]
